# ✅ SAFE PATTERN: Re-instantiate mutable inside call
def safe_append(element, target=None):
    if target is None:
        target = []
    target.append(element)
    return target

def logger(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with {args} and {kwargs}")
        return func(*args, **kwargs) # Unpacks parameters seamlessly
    return wrapper

class Singleton:
    _instance = None

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

class Date:
    def __init__(self, day, month, year):
        self.day, self.month, self.year = day, month, year

    @classmethod
    def from_string(cls, date_str):
        day, month, year = map(int, date_str.split('-'))
        return cls(day, month, year) # Alternative factory constructor

class BoundedNumber:
    def __init__(self, min_val, max_val):
        self.min_val = min_val
        self.max_val = max_val

    def __set_name__(self, owner, name):
        self.name = name

    def __set__(self, instance, value):
        if not (self.min_val <= value <= self.max_val):
            raise ValueError(f"{self.name} out of bounds")
        instance.__dict__[self.name] = value

from functools import wraps

def repeat(num_times):
    def decorator(func):
        @wraps(func) # Preserves docstrings and name
        def wrapper(*args, **kwargs):
            for _ in range(num_times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

class ManagedFile:
    def __init__(self, filename):
        self.filename = filename

    def __enter__(self):
        self.file = open(self.filename, 'w')
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.file:
            self.file.close()
        return False # Propagate exceptions if any occurred

class UpperAttributeMeta(type):
    def __new__(cls, name, bases, dct):
        # Convert all attribute names to uppercase at class creation time
        uppercase_dct = {k.upper(): v for k, v in dct.items() if not k.startswith('__')}
        return super().__new__(cls, name, bases, uppercase_dct)

class CustomClass(metaclass=UpperAttributeMeta):
    feature = "data"

